var rows = new List<ArcTreeTableRow>
{
    new()
    {
        Id = "product",
        Label = "Product",
        ["project"] = "Product",
        ["budget"] = 66750d,
        Children =
        {
            new ArcTreeTableRow { Id = "atlas", Label = "Atlas redesign", ["project"] = "Atlas redesign", ["budget"] = 48250d },
            new ArcTreeTableRow { Id = "billing", Label = "Billing migration", ["project"] = "Billing migration", ["budget"] = 18500d }
        }
    },
    new() { Id = "cloud-archive", Label = "Cloud archive", HasChildren = true }
};

var table = new ArcTreeTable
{
    Rows = rows,
    Label = "Q3 project budgets",
    Selectable = true,
    DefaultExpandedIds = new[] { "product" },
    DefaultSelectedIds = new[] { "atlas" },
    DefaultSort = new ArcTreeTableSort { Key = "budget", Descending = true },
    Columns = new List<ArcTreeTableColumn>
    {
        new() { Key = "project", Header = "Project", Width = 0, MinWidth = 240 },
        new() { Key = "budget", Header = "Budget", Width = 140, Align = ArcTreeTableAlign.Right }
    },
    LoadChildren = async row =>
    {
        await Task.Delay(200);
        return new[] { new ArcTreeTableRow { Id = "archive-2025", Label = "2025 archive" } };
    }
};

table.RowActivated += (_, row) => Console.WriteLine(row.Id);
